SELECT s.id, s.symbol, s.generated_at, s.decision, s.confluence_status, s.confluence_entry_allowed, s.confluence_higher_interval, s.confluence_higher_decision, s.confluence_higher_trend_score, s.confluence_higher_signal_generated_at, s.confluence_evaluated_at, s.atr_entry_type, s.atr_recommended_position_percent, s.atr_immediate_entry_allowed, s.atr_retracement_entry_price, s.atr_overextended, s.candle_range_atr_multiple, s.entry_authority, s.entry_authority_max_position_percent, LEFT(s.entry_authority_explanation, 600) AS entry_authority_explanation, LEFT(s.final_decision_explanation, 800) AS final_decision_explanation FROM trade_signal s WHERE s.id IN (156723,159408,165412,167668,171589,176710) ORDER BY s.id